import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import ToggleButton from '../../components/common/ToggleButton/ToggleButton';
import advertService from '../../services/advertService';
import styles from './AddAdvertPage.module.css';

const AddAdvertPage = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const { t } = useLanguage();
    const { theme } = useTheme();
    const [searchParams] = useSearchParams();
    const editId = searchParams.get('edit');
    const [loading, setLoading] = useState(false);
    const [errors, setErrors] = useState({});
    const [formData, setFormData] = useState({
        address: '', date: '', startTime: '18:00', endTime: '20:00',
        gameLevel: 'D2', cost: '', peopleCount: '', description: ''
    });
    const levels = ['D1', 'D2', 'D3', 'D4', 'D4Plus'];

    useEffect(() => { if (editId) loadAdvert(editId); }, [editId]);

    const loadAdvert = async (id) => {
        try {
            const response = await advertService.getAdvertById(id);
            const advert = response.advert;
            setFormData({
                address: advert.address, date: advert.date, startTime: advert.startTime?.slice(0,5),
                endTime: advert.endTime?.slice(0,5), gameLevel: advert.gameLevel, cost: advert.cost,
                peopleCount: advert.peopleCount, description: advert.description || ''
            });
        } catch (err) { setErrors({ general: t('loadError') }); }
    };

    const validateAddress = (address) => {
        if (!address) return 'Адрес обязателен';
        if (address.length < 5) return 'Введите корректный адрес';
        return '';
    };

    const validateDate = (date) => {
        if (!date) return 'Дата обязательна';

        const selectedDate = new Date(date);
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        const maxDate = new Date(today);
        maxDate.setFullYear(today.getFullYear() + 1);

        if (selectedDate < today) return 'Дата не может быть в прошлом';
        if (selectedDate > maxDate) return 'Дата не может быть позже чем через год';
        return '';
    };

    const validateTime = (startTime, endTime) => {
        if (!startTime) return 'Время начала обязательно';
        if (!endTime) return 'Время окончания обязательно';

        const start = startTime.split(':');
        const end = endTime.split(':');
        const startMinutes = parseInt(start[0]) * 60 + parseInt(start[1]);
        const endMinutes = parseInt(end[0]) * 60 + parseInt(end[1]);

        if (startMinutes >= endMinutes) {
            return 'Время начала не может быть позже времени окончания';
        }

        let duration = endMinutes - startMinutes;
        if (duration < 60) return 'Минимальная продолжительность - 1 час';
        if (duration > 180) return 'Максимальная продолжительность - 3 часа';
        return '';
    };

    const validateCost = (cost) => {
        if (cost === '' || cost === null || cost === undefined) return 'Стоимость обязательна';
        const numValue = parseFloat(cost);
        if (isNaN(numValue)) return 'Введите число';
        if (numValue < 0) return 'Стоимость не может быть отрицательной';
        if (numValue >= 100) return 'Стоимость не может быть больше 99 BYN';
        return '';
    };

    const validatePeopleCount = (count) => {
        if (count === '' || count === null || count === undefined) return 'Количество участников обязательно';
        const numValue = parseInt(count, 10);
        if (isNaN(numValue)) return 'Введите число';
        if (numValue < 2) return 'Минимум 2 участника';
        if (numValue > 50) return 'Максимум 50 участников';
        return '';
    };

    const validateGameLevel = (level) => {
        if (!level) return 'Выберите уровень игры';
        return '';
    };

    const validateField = (name, value) => {
        switch (name) {
            case 'address': return validateAddress(value);
            case 'date': return validateDate(value);
            case 'startTime': return validateTime(value, formData.endTime);
            case 'endTime': return validateTime(formData.startTime, value);
            case 'cost': return validateCost(value);
            case 'peopleCount': return validatePeopleCount(value);
            case 'gameLevel': return validateGameLevel(value);
            default: return '';
        }
    };

    const handleFieldChange = (name, value) => {
        setFormData({ ...formData, [name]: value });
        const error = validateField(name, value);
        setErrors({ ...errors, [name]: error });
    };

    const validateForm = () => {
        const newErrors = {
            address: validateAddress(formData.address),
            date: validateDate(formData.date),
            startTime: validateTime(formData.startTime, formData.endTime),
            endTime: validateTime(formData.startTime, formData.endTime),
            cost: validateCost(formData.cost),
            peopleCount: validatePeopleCount(formData.peopleCount),
            gameLevel: validateGameLevel(formData.gameLevel)
        };
        setErrors(newErrors);
        return Object.values(newErrors).every(error => error === '');
    };

    const handleCostChange = (e) => {
        let value = e.target.value;
        if (value === '' || value === '-') {
            handleFieldChange('cost', '');
            return;
        }
        let numValue = parseFloat(value);
        if (isNaN(numValue)) numValue = 0;
        if (numValue < 0) numValue = 0;
        if (numValue >= 100) numValue = 99.99;
        handleFieldChange('cost', numValue);
    };

    const handlePeopleCountChange = (e) => {
        let value = e.target.value;
        if (value === '' || value === '-') {
            handleFieldChange('peopleCount', '');
            return;
        }
        let numValue = parseInt(value, 10);
        if (isNaN(numValue)) numValue = 2;
        if (numValue < 2) numValue = 2;
        if (numValue > 50) numValue = 50;
        handleFieldChange('peopleCount', numValue);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!validateForm()) return;
        setLoading(true);
        setErrors({});

        try {
            const formDataToSend = {
                ...formData,
                date: formData.date,
                cost: parseFloat(formData.cost),
                peopleCount: parseInt(formData.peopleCount, 10)
            };

            if (editId) {
                await advertService.updateAdvert(editId, formDataToSend);
            } else {
                await advertService.createAdvert(formDataToSend);
            }
            navigate('/');
        } catch (err) {
            setErrors({ general: err.message || t('saveError') });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className={styles.addAdvertPage}>
            <div className={styles.container}>
                <div className={styles.card}>
                    <h1 className={styles.title}>{editId ? t('editAdvert') : t('createAdvertTitle')}</h1>
                    {errors.general && <div className={styles.error}>{errors.general}</div>}

                    <form onSubmit={handleSubmit} className={styles.form}>
                        <div className={styles.fieldGroup}>
                            <Input
                                label={t('address')}
                                placeholder={t('addressPlaceholder')}
                                value={formData.address}
                                onChange={(e) => handleFieldChange('address', e.target.value)}
                                required
                            />
                            {errors.address && <span className={styles.fieldError}>{errors.address}</span>}
                        </div>

                        <div className={styles.fieldGroup}>
                            <Input
                                label={t('date')}
                                type="date"
                                value={formData.date}
                                onChange={(e) => handleFieldChange('date', e.target.value)}
                                required
                            />
                            {errors.date && <span className={styles.fieldError}>{errors.date}</span>}
                        </div>

                        <div className={styles.timeRow}>
                            <div className={styles.fieldGroup}>
                                <Input
                                    label={t('startTime')}
                                    type="time"
                                    value={formData.startTime}
                                    onChange={(e) => handleFieldChange('startTime', e.target.value)}
                                    required
                                />
                                {errors.startTime && <span className={styles.fieldError}>{errors.startTime}</span>}
                            </div>
                            <div className={styles.fieldGroup}>
                                <Input
                                    label={t('endTime')}
                                    type="time"
                                    value={formData.endTime}
                                    onChange={(e) => handleFieldChange('endTime', e.target.value)}
                                    required
                                />
                                {errors.endTime && <span className={styles.fieldError}>{errors.endTime}</span>}
                            </div>
                        </div>

                        <div className={styles.levelSection}>
                            <label className={styles.label}>{t('gameLevel')}</label>
                            <div className={styles.levelButtons}>
                                {levels.map(level => (
                                    <ToggleButton
                                        key={level}
                                        label={level === 'D4Plus' ? 'D4+' : level}
                                        isActive={formData.gameLevel === level}
                                        onClick={() => handleFieldChange('gameLevel', level)}
                                    />
                                ))}
                            </div>
                            {errors.gameLevel && <span className={styles.fieldError}>{errors.gameLevel}</span>}
                        </div>

                        <div className={styles.row}>
                            <div className={styles.fieldGroup}>
                                <Input
                                    label={t('cost')}
                                    type="number"
                                    step="0.01"
                                    min="0"
                                    max="99.99"
                                    placeholder="25"
                                    value={formData.cost}
                                    onChange={handleCostChange}
                                    required
                                />
                                {errors.cost && <span className={styles.fieldError}>{errors.cost}</span>}
                            </div>
                            <div className={styles.fieldGroup}>
                                <Input
                                    label={t('peopleCount')}
                                    type="number"
                                    min="2"
                                    max="50"
                                    placeholder="12"
                                    value={formData.peopleCount}
                                    onChange={handlePeopleCountChange}
                                    required
                                />
                                {errors.peopleCount && <span className={styles.fieldError}>{errors.peopleCount}</span>}
                            </div>
                        </div>

                        <textarea
                            className={styles.textarea}
                            placeholder={t('descriptionPlaceholder')}
                            rows="4"
                            value={formData.description}
                            onChange={(e) => setFormData({...formData, description: e.target.value})}
                        />

                        <div className={styles.actions}>
                            <Button type="button" variant="outline" onClick={() => navigate(-1)}>{t('cancel')}</Button>
                            <Button type="submit" loading={loading}>{editId ? t('save') : t('create')}</Button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default AddAdvertPage;
